/**
 * Form-associated controls must submit their current single and multi-value state.
 * TEST_BUILT=1 exercises the distribution generated by npm run build:web.
 */
import assert from 'node:assert/strict';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';
import { createServer } from 'vite';

const playground = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const repo = path.dirname(playground);
const built = process.env.TEST_BUILT === '1';
const server = await createServer({
    configFile: false,
    root: playground,
    logLevel: 'error',
    server: { host: '127.0.0.1', port: 0, fs: { allow: [repo] } },
    optimizeDeps: { entries: ['tests/form-associated-toggles.html'] },
    resolve: {
        alias: [{
            find: /^@verbb\/plugin-kit-web\/components\/(.+)\.js$/,
            replacement: `${repo}/plugin-kit-web/${built ? 'dist' : 'src'}/components/$1.${built ? 'js' : 'ts'}`,
        }],
    },
});
let browser;

try {
    await server.listen();
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    await page.goto(`${server.resolvedUrls.local[0]}tests/form-associated-toggles.html`);
    await page.locator('body[data-ready="true"]').waitFor({ state: 'attached' });

    const result = await page.evaluate(async () => {
        const createFixture = async (checked = false) => {
            document.querySelector('form')?.remove();
            const form = document.createElement('form');
            form.innerHTML = `
                <pk-checkbox name="agree" checkboxvalue="yes" ${checked ? 'checked' : ''}>Agree</pk-checkbox>
                <pk-lightswitch name="notify" value="1" ${checked ? 'checked' : ''}></pk-lightswitch>
            `;
            document.body.append(form);

            const checkbox = form.querySelector('pk-checkbox');
            const lightswitch = form.querySelector('pk-lightswitch');
            await Promise.all([checkbox.updateComplete, lightswitch.updateComplete]);

            return { form, checkbox, lightswitch };
        };
        const entries = (form) => [...new FormData(form).entries()];
        const expected = [['agree', 'yes'], ['notify', '1']];
        const results = {};

        let fixture = await createFixture();
        results.initiallyUnchecked = entries(fixture.form);
        fixture.checkbox.shadowRoot.querySelector('input').click();
        fixture.lightswitch.shadowRoot.querySelector('[part="switch"]').click();
        await Promise.all([fixture.checkbox.updateComplete, fixture.lightswitch.updateComplete]);
        results.afterPointerOn = entries(fixture.form);

        fixture.checkbox.shadowRoot.querySelector('input').click();
        fixture.lightswitch.shadowRoot.querySelector('[part="switch"]').click();
        await Promise.all([fixture.checkbox.updateComplete, fixture.lightswitch.updateComplete]);
        results.afterPointerOff = entries(fixture.form);

        fixture.checkbox.checked = true;
        fixture.lightswitch.checked = true;
        await Promise.all([fixture.checkbox.updateComplete, fixture.lightswitch.updateComplete]);
        results.afterProgrammaticOn = entries(fixture.form);

        fixture.checkbox.checked = false;
        fixture.lightswitch.checked = false;
        await Promise.all([fixture.checkbox.updateComplete, fixture.lightswitch.updateComplete]);
        results.afterProgrammaticOff = entries(fixture.form);

        fixture = await createFixture(true);
        results.initiallyChecked = entries(fixture.form);
        fixture.checkbox.shadowRoot.querySelector('input').click();
        fixture.lightswitch.shadowRoot.querySelector('[part="switch"]').click();
        await Promise.all([fixture.checkbox.updateComplete, fixture.lightswitch.updateComplete]);
        results.initiallyCheckedAfterPointerOff = entries(fixture.form);

        fixture = await createFixture(true);
        fixture.checkbox.checkboxValue = 'no';
        await fixture.checkbox.updateComplete;
        results.afterCheckboxValueChange = entries(fixture.form);

        fixture.form.remove();
        const radioForm = document.createElement('form');
        radioForm.innerHTML = `
            <pk-radio-group name="choice" value="a">
                <pk-radio value="a">A</pk-radio>
                <pk-radio value="b">B</pk-radio>
            </pk-radio-group>
        `;
        document.body.append(radioForm);
        const radioGroup = radioForm.querySelector('pk-radio-group');
        const radios = [...radioForm.querySelectorAll('pk-radio')];
        await Promise.all([radioGroup.updateComplete, ...radios.map((radio) => radio.updateComplete)]);
        await new Promise((resolve) => setTimeout(resolve, 0));
        await radioGroup.updateComplete;
        results.radioInitial = entries(radioForm);

        radios[1].shadowRoot.querySelector('input').click();
        await radioGroup.updateComplete;
        results.radioAfterPointer = entries(radioForm);

        radioGroup.value = 'a';
        await radioGroup.updateComplete;
        results.radioAfterProgrammatic = entries(radioForm);

        radioForm.remove();
        const multiForm = document.createElement('form');
        multiForm.innerHTML = `
            <pk-select name="fruit" multiple>
                <pk-option value="apple">Apple</pk-option>
                <pk-option value="pear">Pear</pk-option>
            </pk-select>
            <pk-combobox name="color" multiple>
                <pk-option value="red">Red</pk-option>
                <pk-option value="blue">Blue</pk-option>
            </pk-combobox>
        `;
        document.body.append(multiForm);
        const select = multiForm.querySelector('pk-select');
        const combobox = multiForm.querySelector('pk-combobox');
        const selectOptions = [...select.querySelectorAll('pk-option')];
        const comboboxOptions = [...combobox.querySelectorAll('pk-option')];
        await Promise.all([
            select.updateComplete,
            combobox.updateComplete,
            ...selectOptions.map((option) => option.updateComplete),
            ...comboboxOptions.map((option) => option.updateComplete),
        ]);
        results.multiInitial = entries(multiForm);

        await select.show();
        selectOptions[0].shadowRoot.querySelector('button').click();
        await select.updateComplete;
        await combobox.show();
        comboboxOptions[0].shadowRoot.querySelector('button').click();
        await combobox.updateComplete;
        results.multiAfterPointer = entries(multiForm);

        select.values = ['apple', 'pear'];
        combobox.values = ['red', 'blue'];
        await Promise.all([select.updateComplete, combobox.updateComplete]);
        results.multiAfterProgrammatic = entries(multiForm);

        select.values = [];
        combobox.values = [];
        await Promise.all([select.updateComplete, combobox.updateComplete]);
        results.multiAfterClear = entries(multiForm);

        return { expected, results };
    });

    const { expected, results } = result;
    assert.deepEqual(results.initiallyUnchecked, []);
    assert.deepEqual(results.afterPointerOn, expected);
    assert.deepEqual(results.afterPointerOff, []);
    assert.deepEqual(results.afterProgrammaticOn, expected);
    assert.deepEqual(results.afterProgrammaticOff, []);
    assert.deepEqual(results.initiallyChecked, expected);
    assert.deepEqual(results.initiallyCheckedAfterPointerOff, []);
    assert.deepEqual(results.afterCheckboxValueChange, [['agree', 'no'], ['notify', '1']]);
    assert.deepEqual(results.radioInitial, [['choice', 'a']]);
    assert.deepEqual(results.radioAfterPointer, [['choice', 'b']]);
    assert.deepEqual(results.radioAfterProgrammatic, [['choice', 'a']]);
    assert.deepEqual(results.multiInitial, []);
    assert.deepEqual(results.multiAfterPointer, [['fruit', 'apple'], ['color', 'red']]);
    assert.deepEqual(results.multiAfterProgrammatic, [
        ['fruit', 'apple'],
        ['fruit', 'pear'],
        ['color', 'red'],
        ['color', 'blue'],
    ]);
    assert.deepEqual(results.multiAfterClear, []);
    assert.deepEqual(errors, [], 'no browser exceptions');
    console.log(`PASS form-associated values (${built ? 'built package' : 'source'})`);
} finally {
    await browser?.close();
    await server.close();
}
